package org.apache.commons.math.stat.descriptive;

import org.apache.commons.math.stat.descriptive.moment.Mean;
import org.apache.commons.math.stat.descriptive.moment.Variance;
import org.apache.commons.math.stat.descriptive.moment.GeometricMean;
import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Math_43_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        SummaryStatistics stats = new SummaryStatistics();

        // Custom implementations
        Mean customMean = new Mean();
        Variance customVariance = new Variance();
        GeometricMean customGeoMean = new GeometricMean();

        // Set custom implementations using setter methods
        stats.setMeanImpl(customMean);
        stats.setVarianceImpl(customVariance);
        stats.setGeoMeanImpl(customGeoMean);

        // Add a value
        double value = 5.0;
        stats.addValue(value);

        // Check if custom implementations have been incremented
        assertEquals("Custom mean should be incremented", value, customMean.getResult(), 0.0001);
        assertEquals("Custom variance should be incremented", 0.0, customVariance.getResult(), 0.0001);
        assertEquals("Custom geometric mean should be incremented", value, customGeoMean.getResult(), 0.0001);
    }
}

